--
-- Triggers `articulo_ventas`
--
DELIMITER $$
CREATE TRIGGER `tr_updStockVenta` AFTER INSERT ON `articulo_ventas` FOR EACH ROW BEGIN
        UPDATE articulos SET stock = stock - NEW.cantidad
        WHERE articulos.id = NEW.articulo_id;
        END
$$
