--
-- Table structure for table `cortesias`
--

CREATE TABLE `cortesias` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `nombre_cliente` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
